        <ul aria-label="People found">
          @for (f of found(); track $index) {
            <li data-testid="search-line">{{ f.sheet }} {{ f.name }} {{ f.dueTotal }}</li>
          }
        </ul>
      }
      @if (error()) {
        <p role="alert" data-testid="search-error">{{ error() }}</p>
      }
    </div>
